```cpp
#include<iostream>
using namespace std;
int func(int x,int y)
{
    int a=x,b=y;
    int t;
    t=a;
    a=b;
    b=t;
    cout<<a<<" "<<b<<" ";
}
int main()
{
    int c,d;
    c=12;
    d=24;
    func(12,24);
    cout<<c<<" "<<d<<endl;
}
```

