下列程序横线处，应该输入的是（ ）。

```cpp
#include<iostream>
using namespace std;
int n,a[10001];
void swap(int &a,int &b)
{
    int t=a;
    a=b;
    b=t;
}
int main()
{
    cin>>n;
    for(int i=1;i<=n;i++)
        cin>>a[i];
    for(int i=n;i>1;i--)
        for(int j=1;j<i;j++)
            if(a[j]>a[j+1])
                __________;
    for(int i=1;i<=n;i++)
        cout<<a[i]<<" ";
    cout<<endl;
    return 0;
}
```

下面的排序算法程序中，横线处应该填入的是（ ）。

```cpp
int a[8]={ 2,3, 4, 5, 6,2,3,1};
for (int i=1;i<8;i++)
{

    int key = a[i];
    int j=i-1;
    while(a[j]>key && j>=0)
    {
        ________;
        j -= 1;
    }
    a[j + 1]= key;
}
```

下面的程序中，如果输入 10 0 ，会输出（ ）。

```cpp
#include<iostream>
using namespace std;

double Division(int a, int b)
{

    if (b == 0)
        throw "Division by zero condition!";

    else
        return ((double)a / (double)b);
}

void func()
{
    int len, time;
    cin >> len >> time;
    cout << Division(len, time) << endl;
}

int main()
{
    try {
        func();
    }
    catch (const char* errmsg)
    {
        cout << errmsg << endl;
    }
    catch (const int errmsg)
    {
        cout << errmsg << endl;
    }
    return 0;
}
```

